// (trm 1024) the MLP's act as silu(s g) (s u) in f16 on every PE of the column, from
// the gate-up all-reduce's gu: no act gather. e = exp(-|a|) as 2^n 2^r (degree 3),
// 1 / (1 + e) by a quadratic and one Newton step, a sig(a) = max(a, a e) / (1 + e).
// G | U in act (free in the MLP), B then D in xpart (the result's place), A | C here
// (also exp_fast's u16 scratch, ek's place).
var sg16b = @zeros([2 * Ic]@fp16());   // A | C (G | U in act, B and D in xpart)
const sg_g = @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{Ic} -> gu[i] });
