const sg_gu = @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{2 * Ic} -> gu[i] });
const sgA = @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{Ic} -> sg16b[i] });
const sgC = @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{Ic} -> sg16b[@as(i16, Ic) + i] });
const sgB = @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{Ic} -> xpart[i] });
const sgD = sgB;
const sgO = sgB;
const sg_t16 = @get_dsd(mem1d_dsd, .{ .base_address = &ek[0], .extent = Ic });
var sgG = sgA;
var sgU = sgA;
var sgGb = sg_t16;
var sgAb = sg_t16;
