fn silu16_setup() void {
  ex16 = @set_dsd_base_addr(ex16, @ptrcast([*]u16, &sg16b[0]));   // exp_fast's scratch: sg16b (free outside the MLP)
  sgG = @set_dsd_base_addr(sgA, @ptrcast([*]@fp16(), &act[0]));
  sgU = @set_dsd_base_addr(sgA, @ptrcast([*]@fp16(), &act[Ic / 2]));
  sgGb = @set_dsd_base_addr(sg_t16, @ptrcast([*]u16, &act[0]));
  sgAb = @set_dsd_base_addr(sg_t16, @ptrcast([*]u16, &sg16b[0]));
  sgBb = @set_dsd_base_addr(sg_t16, @ptrcast([*]u16, &xpart[0]));
