fn silu16(sc: f32) void {
  @fmuls(sg_g, sg_g, sc * 1.4426950408889634);   // a' = s g log2e
  @fmuls(sg_u, sg_u, sc * 0.6931471805599453);   // u' = s u ln2
  @fs2h(@set_dsd_length(sgG, 2 * Ic), sg_gu);
  @or16(sgAb, sgGb, 0x8000);                     // t = -|a'|
  @fmaxh(sgA, sgA, @as(@fp16(), -15.0));
  @faddh(sgB, sgA, @as(@fp16(), 1536.0));        // m: round(t) in its low bits
  @faddh(sgC, sgB, @as(@fp16(), -1536.0));
  @fsubh(sgA, sgA, sgC);                         // r = t - n
  @fmulh(sgC, sgA, @as(@fp16(), 0.05516966520599117));
  @faddh(sgC, sgC, @as(@fp16(), 0.24260644929856207));
  @fmulh(sgC, sgC, sgA);
  @faddh(sgC, sgC, @as(@fp16(), 0.6932608957863087));
  @fmulh(sgC, sgC, sgA);
  @faddh(sgC, sgC, @as(@fp16(), 0.9999283788785166));   // 2^r
  @add16(sgBb, sgBb, 0x9a0f);                    // n + 15 (1536 is 0x6600)
  @sll16(sgBb, sgBb, 10);                        // 2^n
  @fmulh(sgC, sgC, sgB);                         // e
  @faddh(sgA, sgC, @as(@fp16(), 1.0));           // d
  @fmulh(sgD, sgA, @as(@fp16(), 0.323112507040746));
  @faddh(sgD, sgD, @as(@fp16(), -1.4540415401729079));
  @fmulh(sgD, sgD, sgA);
  @faddh(sgD, sgD, @as(@fp16(), 2.1207294161729284));
  @fmulh(sgA, sgA, sgD);
  @fsubh(sgA, @as(@fp16(), 2.0), sgA);
  @fmulh(sgD, sgD, sgA);                         // 1 / d
  @fmulh(sgC, sgC, sgG);
  @fmaxh(sgC, sgC, sgG);
  @fmulh(sgC, sgC, sgU);
  @fmulh(sgO, sgC, sgD);
}
